import { Component, OnInit } from '@angular/core';
import { HttpClient } from '@angular/common/http';

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent implements OnInit {
  tables: any[] = [];
  selectedTable: string = '';
  tableData: any[] = [];
  
  newEmp = { name: '', position: '', salary: 0 };

  constructor(private http: HttpClient) {}

  ngOnInit() {
    this.loadTables();
  }

  loadTables() {
    this.http.get<any[]>('http://localhost:3000/tables')
      .subscribe({
        next: (data) => this.tables = data,
        error: (e) => console.error(e)
      });
  }

  onTableSelect(event: any) {
    this.selectedTable = event.target.value;
    this.loadTableData();
  }

  loadTableData() {
    if(!this.selectedTable) return;
    this.http.get<any[]>(`http://localhost:3000/data/${this.selectedTable}`)
      .subscribe({
        next: (data) => this.tableData = data,
        error: (e) => console.error(e)
      });
  }

  addEmployee() {
    this.http.post('http://localhost:3000/add-employee', this.newEmp)
      .subscribe(() => {
        this.loadTableData();
        this.newEmp = { name: '', position: '', salary: 0 };
      });
  }
}
